+            var noopTotal = getRecordedMetric(plugin::getLongAsyncCounterMeasurement, "es.indices.noop.total");
+            assertThat(noopTotal.getLong(), equalTo(0L));
+
+            var coordinatingOperationsSize = getRecordedMetric(
