+            assertThat(coordinatingOperationsSize.getLong(), greaterThan(0L));
+
+            var coordinatingOperationsTotal = getRecordedMetric(
+                plugin::getLongAsyncCounterMeasurement,
+                "es.indexing.coordinating_operations.total"
+            );
